def _tally_prune_chain_rows(
    rows: list[dict], threshold: int
) -> tuple[str, list | None]:
    """Re-tally the stage's rows honoring the append-only union order.

    ``rows`` walks the stage in union order -- the predecessor's
    existing statements first (their original order), then the new
    handover statements -- so the first occurrence of one site/content
    group is always the historical one: it stays ``valid`` and only
    later repeats become ``duplicate``; a second distinct declaration
    from one site contradicts every declaration of that site.
    Distinct sites must share the one declaration; any disagreement is
    ``conflicted`` and no majority can outvote it.  One unique
    conflict-free declaration backed by at least the threshold of
    distinct sites is ``accepted``; short of the threshold it stays
    ``insufficient`` but keeps that declaration; with no valid vote the
    declaration is null.
    """
    # site -> content bytes -> list of (union position, row)
    by_site: dict[str, dict[bytes, list[tuple[int, dict]]]] = {}
    for position, row in enumerate(rows):
        if row[ADJ_CONCLUSION] in (
            PA_CONCLUSION_VALID,
            PA_CONCLUSION_DUPLICATE,
            PA_CONCLUSION_CONTRADICTION,
        ):
            content = _prune_compact(row[PBA_DECLARATION])
            by_site.setdefault(row[VD_ISSUER], {}).setdefault(
                content, []
            ).append((position, row))

    contradicted = False
    votes: dict[str, bytes] = {}
    representatives: dict[str, tuple[int, dict]] = {}
    for site, groups in by_site.items():
        if len(groups) > 1:
            contradicted = True
            for members in groups.values():
                members[0][1][ADJ_CONCLUSION] = PA_CONCLUSION_CONTRADICTION
                members[0][1][ADJ_REASON] = REASON_CONTRADICTION
                for _position, extra in members[1:]:
                    extra[ADJ_CONCLUSION] = PA_CONCLUSION_DUPLICATE
                    extra[ADJ_REASON] = REASON_DUPLICATE
        else:
            content, members = next(iter(groups.items()))
            members[0][1][ADJ_CONCLUSION] = PA_CONCLUSION_VALID
            members[0][1][ADJ_REASON] = None
            for _position, extra in members[1:]:
                extra[ADJ_CONCLUSION] = PA_CONCLUSION_DUPLICATE
                extra[ADJ_REASON] = REASON_DUPLICATE
            votes[site] = content
            representatives[site] = members[0]

    contents = set(votes.values())
    if contradicted or len(contents) > 1:
        return PA_STATUS_CONFLICTED, None
    if len(contents) == 1:
        # The representative is the earliest valid row in union order.
        _position, representative = min(
            representatives.values(), key=lambda member: member[0]
        )
        common_declaration = copy.deepcopy(
            representative[PBA_DECLARATION]
        )
        if len(votes) >= threshold:
            return PA_STATUS_ACCEPTED, common_declaration
        return PA_STATUS_INSUFFICIENT, common_declaration
    return PA_STATUS_INSUFFICIENT, None

